import{_ as a,C as i,o as t,c as d,j as e,a as r,E as n,a5 as l}from"./chunks/framework.B1qnvv14.js";const F=JSON.parse('{"title":"Isolamento de recursos","description":"","frontmatter":{"title":"Isolamento de recursos"},"headers":[],"relativePath":"isolamento.md","filePath":"isolamento.md","lastUpdated":1793391883000}'),c={name:"isolamento.md"};function p(h,s,m,k,u,g){const o=i("CopyOrDownloadAsMarkdownButtons");return t(),d("div",null,[s[0]||(s[0]=e("h1",{id:"isolamento-de-recursos",tabindex:"-1"},[r("Isolamento de recursos "),e("a",{class:"header-anchor",href:"#isolamento-de-recursos","aria-label":'Permalink to "Isolamento de recursos"'},"​")],-1)),n(o),s[1]||(s[1]=l(`<p>Opcional. Disponível em Linux com systemd e Docker usando o driver de cgroup <code>systemd</code>.</p><p>Com várias stacks no ar, um teste descontrolado em uma task pode consumir toda a memória e travar a máquina. Com o isolamento ligado, tudo o que uma task roda entra em um slice systemd próprio, <code>automacli-slot&lt;N&gt;.slice</code>, com limite de memória e peso de CPU reduzido (<code>CPUWeight=50</code>: a task perde a disputa de CPU para o desktop, sem teto fixo). Quem estoura o limite de memória é morto dentro do slice, e o resto da máquina segue respondendo.</p><h2 id="ligar" tabindex="-1">Ligar <a class="header-anchor" href="#ligar" aria-label="Permalink to &quot;Ligar&quot;">​</a></h2><p>No perfil do repositório:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">isolation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pidsLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span></span></code></pre></div><p>E, uma vez por máquina, instale os slices e os limites a partir do repositório do automacli:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-system-limits.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # slices, systemd-oomd, sysctl e daemon.json do Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-user-limits.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # slices da sessão do usuário</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # quando for conveniente</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Atenção</p><p><code>install-system-limits.sh</code> altera <code>/etc/docker/daemon.json</code> (define <code>cgroup-parent</code>, <code>live-restore</code> e, se ainda não houver, <code>default-address-pools</code>; guarda um backup em <code>daemon.json.bak-automacli</code>) e o primeiro restart do Docker derruba os containers em execução. Leia o script antes de rodar.</p></div><p>Sem os slices instalados, o <code>cgroup_parent</code> ainda agrupa os containers por slot, mas <strong>sem limite de memória nem de CPU</strong>; só o <code>pids_limit</code> por container, aplicado pelo Docker, continua valendo.</p><h2 id="como-cada-coisa-entra-no-slice" tabindex="-1">Como cada coisa entra no slice <a class="header-anchor" href="#como-cada-coisa-entra-no-slice" aria-label="Permalink to &quot;Como cada coisa entra no slice&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O que roda</th><th>Como entra</th><th>Onde ficam os limites</th></tr></thead><tbody><tr><td>Containers da stack</td><td><code>cgroup_parent</code> no override</td><td><code>/etc/systemd/system/automacli-.slice.d/</code></td></tr><tr><td>Containers de teste</td><td><code>cgroup_parent</code> em <code>docker-compose.limits.yml</code>, ao lado de cada <code>compose.testFile</code></td><td>idem</td></tr><tr><td>Outros containers</td><td><code>cgroup-parent: automacli.slice</code> no <code>daemon.json</code></td><td><code>/etc/systemd/system/automacli.slice</code> (teto global)</td></tr><tr><td>Processos do host</td><td><code>systemd-run --user --scope --slice=automacli-slot&lt;N&gt;.slice</code></td><td><code>~/.config/systemd/user/automacli-.slice.d/</code></td></tr></tbody></table><p>O automacli decide <strong>onde</strong> cada processo roda. <strong>Quanto</strong> ele pode usar fica na pasta <code>system/</code> do repositório, nunca no código: tetos globais nos arquivos <code>.slice</code>, limites por slot nos <code>.conf</code>.</p><h3 id="arquivos-de-teste" tabindex="-1">Arquivos de teste <a class="header-anchor" href="#arquivos-de-teste" aria-label="Permalink to &quot;Arquivos de teste&quot;">​</a></h3><p>O Compose rejeita um override que mencione um serviço ausente dos arquivos passados com <code>-f</code>. Por isso os testes não podem reaproveitar o override da stack: para cada arquivo com o nome de <code>compose.testFile</code>, o automacli grava ao lado um <code>docker-compose.limits.yml</code> com os serviços daquele teste e os de <code>compose.testBaseFiles</code>. Inclua-o no comando de teste:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.base.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/api/docker-compose.test.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/api/docker-compose.limits.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span></span></code></pre></div><h3 id="processos-do-host" tabindex="-1">Processos do host <a class="header-anchor" href="#processos-do-host" aria-label="Permalink to &quot;Processos do host&quot;">​</a></h3><p>Para <code>pnpm</code>, <code>jest</code> e afins rodando fora do Docker, use um wrapper nos seus <a href="./instalacao#estrutura-do-diretorio-de-configuracao">templates</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scripts/isolate.sh — uso: scripts/isolate.sh pnpm test</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SLOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -oE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;slot&quot;:[[:space:]]*[0-9]+&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .slot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -oE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[0-9]+$&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slice=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;automacli-slot\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SLOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.slice&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h2 id="saber-o-que-foi-morto" tabindex="-1">Saber o que foi morto <a class="header-anchor" href="#saber-o-que-foi-morto" aria-label="Permalink to &quot;Saber o que foi morto&quot;">​</a></h2><p>Um serviço morto por falta de memória não avisa: o container some ou reinicia, e o sintoma aparece em outro lugar (um <code>502</code> no proxy, um teste que termina com <code>Killed</code>). Há três formas de ver o que aconteceu:</p><table tabindex="0"><thead><tr><th>Como</th><th>Quando usar</th></tr></thead><tbody><tr><td><code>automacli oom</code></td><td>Depois do fato: lista quem morreu, quando, em qual slot e por quê.</td></tr><tr><td>Notificação do <a href="./monitor#notificacoes">monitor</a></td><td>Na hora: aviso de desktop em até 30 segundos.</td></tr><tr><td><code>GET /api/oom</code> e o campo <code>oomKills</code> de cada task</td><td>Para painéis e agentes de IA.</td></tr></tbody></table><p>Como ler o motivo:</p><ul><li><strong><code>memory pressure for /automacli.slice/automacli-slot4.slice</code></strong>: o slot 4 sozinho passou do limite. O problema está naquela task.</li><li><strong><code>memory pressure for /automacli.slice</code></strong>: a soma de todas as stacks passou do teto global. Quem morre é o maior consumidor, que pode não ser o culpado. Pare stacks que não está usando.</li><li><strong><code>limite de memória de ... atingido</code></strong> (causa <code>kernel</code>): o slice bateu em <code>MemoryMax</code>.</li></ul><p>Um container é identificado pelo nome do serviço enquanto existir no Docker. Depois de removido, só se o monitor (ou um <code>automacli oom</code> anterior) já tinha visto o container; caso contrário aparece como <code>container &lt;id&gt; (removido)</code> nas mortes do oomd, ou só com o nome do processo nas mortes do kernel.</p><h2 id="limites-padrao" tabindex="-1">Limites padrão <a class="header-anchor" href="#limites-padrao" aria-label="Permalink to &quot;Limites padrão&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Escopo</th><th><code>MemoryHigh</code></th><th><code>MemoryMax</code></th><th>Pressão para o oomd matar</th></tr></thead><tbody><tr><td>Containers de um slot</td><td>13 GB</td><td>14 GB</td><td>80% por 20 s</td></tr><tr><td>Todas as stacks juntas</td><td>20 GB</td><td>22 GB</td><td>70% por 20 s</td></tr><tr><td>Processos do host de um slot</td><td>6 GB</td><td>8 GB</td><td>60% por 20 s</td></tr><tr><td>Todos os processos do host juntos</td><td>10 GB</td><td>12 GB</td><td>60% por 20 s</td></tr></tbody></table><p>Os valores partem de uma máquina com 30 GB. Uma stack completa com os front-ends compilando passa de 7 GB; o <code>MemoryHigh</code> fica perto do <code>MemoryMax</code> de propósito, porque é ao atingi-lo que o kernel começa a frear o grupo, e é essa frenagem que o <code>systemd-oomd</code> lê como pressão. Com o High baixo demais, o oomd mata um container durante um pico de compilação mesmo havendo memória sobrando na máquina.</p><p><code>MemoryHigh</code> desacelera o grupo antes de matar; <code>MemoryMax</code> é o teto. O <code>systemd-oomd</code> mata o cgroup (o container, ou o scope do processo do host) que mais pressiona a memória dentro do slice, e o teste falha com <code>Killed</code> ou código 137 em vez de travar a máquina.</p><p>Para mudar, edite os <code>.slice</code> e <code>.conf</code> em <code>system/</code> e rode os scripts de instalação de novo. Antes de subir um limite, tente reduzir o paralelismo do teste (<code>--maxWorkers</code>): o peso de CPU não reduz o número de workers do Jest, que conta as CPUs do host.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Nunca coloque o slice da sua sessão gráfica sob o <code>systemd-oomd</code>. Em muitos ambientes o compositor, os terminais e o navegador vivem no mesmo escopo, e um kill ali encerra a sessão inteira.</p></div>`,30))])}const C=a(c,[["render",p]]);export{F as __pageData,C as default};
